for(const [id,options] of Object.entries(riggingSizes)){
 const base=products.find(p=>p.id===id);base.variants=options;base.from=options[0].price!==undefined;base.rates=options[0].price===undefined?{}:{daily:options[0].price};base.quoteOnly=options[0].price===undefined;base.spec=`${options.length} sizes available`;base.desc=id==="spreaderbars"?"Four-way spreader bars. Choose the dimensions and listed safe working load for your lift.":"Choose the beam length and section size for your lifting arrangement.";
 for(const option of options)products.push({...base,id:option.id,name:`${base.name} — ${option.size}`,spec:option.size,hidden:true,variants:undefined,from:false,quoteOnly:option.price===undefined,rates:option.price===undefined?{}:{daily:option.price},rigging:{...option,family:id}});
}
function riggingIllustration(v){
 const family=v.family||(v.width?"spreaderbars":v.depth?"liftingbeams":"spreaderbeams"),max=family==="liftingbeams"?30:family==="spreaderbars"?13:8;
 const w=280*v.length/max,x=(400-w)/2,y=112,h=family==="liftingbeams"?Math.max(12,v.depth*1.5):22;
 const beam=(bx,by,bw,bh)=>`<path d="M${bx},${by} h${bw} v5 h-${bw} z M${bx+3},${by+5} h${bw-6} v${bh-10} h-${bw-6} z M${bx},${by+bh-5} h${bw} v5 h-${bw} z" fill="#edb526" stroke="#76510b" stroke-width="1.5"/>`;
 const hook=(hx,hy)=>`<path d="M${hx},${hy} v8 c-13,0 -12,20 0,20 c9,0 13,-10 7,-14" fill="none" stroke="#a3070b" stroke-width="4"/>`;
 let shape;
 if(family==="spreaderbars"){
  const d=w*v.width/v.length*.45,dx=d*.55,front=y+30,back=front-d;
  shape=`<path d="M200,34 L${x},${front} M200,34 L${x+dx},${back} M200,34 L${x+w},${front} M200,34 L${x+w+dx},${back}" fill="none" stroke="#30343b" stroke-width="2"/><path d="M${x},${front} l${dx},-${d} h${w} l-${dx},${d} z" fill="none" stroke="#b98819" stroke-width="8"/>`;
  for(const [hx,hy] of [[x,front],[x+dx,back],[x+w,front],[x+w+dx,back]])shape+=`<path d="M${hx},${hy+4} v30" stroke="#30343b" stroke-width="2"/>${hook(hx,hy+34)}`;
 }else{
  shape=beam(x,y,w,h)+hook(x+8,y+h)+hook(x+w-8,y+h);
  shape+=family==="liftingbeams"?`<path d="M${x+10},${y} L200,38 L${x+w-10},${y}" fill="none" stroke="#30343b" stroke-width="5" stroke-dasharray="5 3"/>`:`<path d="M188,${y} V${y-26} Q200,${y-50} 212,${y-26} V${y}" fill="none" stroke="#d39b16" stroke-width="9"/>`;
 }
 return `<svg class="rigging-diagram" viewBox="0 0 400 260" role="img" aria-label="${family==="spreaderbars"?"Four-way rectangular spreader bar":family==="liftingbeams"?"Chain-suspended lifting beam":"Centre-eye spreader beam"}: ${v.size}"><g class="rigging-outline">${shape}</g><path class="dimension-line" d="M${x},215 H${x+w} M${x},208 V222 M${x+w},208 V222" fill="none" stroke="#a3070b" stroke-width="2"/><text x="200" y="240" text-anchor="middle">${v.length}′ length${v.width?` × ${v.width}′ width`:v.depth?` · ${v.depth}″ section`:""}</text>${v.swl?`<text x="200" y="258" text-anchor="middle">${v.swl} Ton SWL · 4 way</text>`:""}</svg><small class="rigging-caption">Shape reference · lengths scaled within each beam type</small>`;
}
function riggingSelector(p){return p.variants?`<div class="rigging-picker"><label>Choose size<select class="rigging-size" aria-label="Size for ${p.name}">${p.variants.map(v=>`<option value="${v.id}">${v.size} · ${v.price===undefined?'Rate to be confirmed':money(v.price)+'/day'}</option>`).join('')}</select></label><div class="rigging-preview">${riggingIllustration(p.variants[0])}</div></div>`:'';}

