function addLine(id,term,qty,details={}){const product=products.find(p=>p.id===id);if(product?.compatibleWith&&!cart.some(parent=>parent.key===details.parentKey&&product.compatibleWith.includes(parent.id)))return;const key=details.parentKey?`${id}:${details.parentKey}:${term}`:`${id}:${term}`,found=cart.find(i=>i.key===key);if(found)found.qty+=qty;else cart.push({key,id,term,qty,...details})}
function minimumQty(p,term){return p.operatorService?1:term==="hourly"?4:1}
function lineAmount(i){const p=products.find(x=>x.id===i.id);return(p?.rates[i.term]||0)*i.qty}
function lineTotal(i,p){return p.quoteOnly?"To be confirmed":money(lineAmount(i))}
function lineRate(i,p){return p.quoteOnly?"Manual rate confirmation":`${termLabels[i.term]} · ${money(p.rates[i.term])} × ${i.qty}`}
function hasQuoteItems(){return cart.some(i=>products.find(p=>p.id===i.id)?.quoteOnly)}
function equipmentSubtotal(){return cart.filter(i=>!products.find(p=>p.id===i.id)?.operatorService).reduce((sum,i)=>sum+lineAmount(i),0)}
function operatorSubtotal(){return cart.filter(i=>products.find(p=>p.id===i.id)?.operatorService).reduce((sum,i)=>sum+lineAmount(i),0)}
function subtotal(){return equipmentSubtotal()+operatorSubtotal()}
function lineName(i,p){return i.label||p.name}
function rewardDiscount(){return rewardsAccount?.discountPercent||0}function rewardSavings(){return equipmentSubtotal()*rewardDiscount()/100}function discountedSubtotal(){return subtotal()-rewardSavings()}
// Fill empty checkout fields from the signed-in customer's account.
function prefillCheckout(profile){if(!profile)return;const f=$("#checkoutForm");if(!f)return;const values={customer_name:profile.name,email:profile.email,phone:profile.phone,company:profile.company};for(const[name,value]of Object.entries(values)){const el=f.elements[name];if(el&&value&&!el.value)el.value=value}}
async function loadRewards(){try{const response=await fetch("/api/rewards",{cache:"no-store"});if(response.ok){const data=await response.json();rewardsAccount=data.rewards;prefillCheckout(data.profile);const accountLink=document.querySelector('.account-button');if(accountLink){accountLink.href='/account/profile';accountLink.textContent=`My profile · ${data.rewards.tier}`;accountLink.title=data.rewards.nextTier ? `CI$${(data.rewards.amountToNextCents/100).toLocaleString()} more to ${data.rewards.nextTier}` : 'Platinum — highest reward tier';}renderCart()}}catch(error){console.info("Rewards account unavailable",error)}}
function renderCart(){const count=cart.length;$("#cartCount").textContent=count;$("#cartItems").innerHTML=cart.map(i=>{const p=products.find(x=>x.id===i.id),quantityLabel=p.operatorService?(i.term==="hourly"?"Hours":"Days"):"Quantity";return `<article class="cart-item ${p.operatorService?"operator-line":""} ${p.quoteOnly?"quote-line":""}"><div class="cart-item-head"><div><h3>${lineName(i,p)}</h3><small>${lineRate(i,p)}</small></div><b>${lineTotal(i,p)}</b></div><div class="cart-item-actions"><label>${quantityLabel}<input type="number" min="${minimumQty(p,i.term)}" value="${i.qty}" data-qty="${i.key}"></label><button class="remove-item" data-remove="${i.key}">Remove</button></div></article>`}).join("");const empty=!cart.length,discount=rewardDiscount(),operatorTotal=operatorSubtotal(),quotePending=hasQuoteItems();$("#cartEmpty").hidden=!empty;$("#cartSummary").hidden=empty;$("#cartSubtotal").textContent=money(equipmentSubtotal())+(quotePending?" + quote":"");$("#cartOperatorRow").hidden=!operatorTotal;$("#cartOperatorSubtotal").textContent=money(operatorTotal);$("#rewardCartRow").hidden=!discount;$("#rewardCartLabel").textContent=discount?`${rewardsAccount.tier} rewards (${discount}%)`:"Rewards discount";$("#rewardCartDiscount").textContent=`−${money(rewardSavings())}`;$("#rewardCartNote").textContent=quotePending?"Items marked for manual pricing are not included in the estimate. Cayman Crane will confirm those rates with availability.":discount?`${rewardsAccount.tier} discount applied to equipment. Operator service, delivery, overtime, fuel and special charges are excluded.`:"Sign in to use your rewards discount. Operator service, delivery, overtime, fuel, damage waivers and special rigging are confirmed separately where applicable.";$$('[data-qty]').forEach(x=>x.onchange=()=>{const i=cart.find(c=>c.key===x.dataset.qty),p=products.find(x=>x.id===i.id);i.qty=Math.max(Number(x.value)||1,minimumQty(p,i.term));saveCart()});$$('[data-remove]').forEach(x=>x.onclick=()=>{const removed=cart.find(c=>c.key===x.dataset.remove);cart=cart.filter(c=>c.key!==x.dataset.remove&&c.parentKey!==removed?.key);saveCart()})}
function openCart(){$("#cartDrawer").classList.add("open");$("#drawerBackdrop").classList.add("open");$("#cartDrawer").setAttribute("aria-hidden","false");$("#cartButton").setAttribute("aria-expanded","true");document.body.classList.add("lock")}
function closeCart(){$("#cartDrawer").classList.remove("open");$("#drawerBackdrop").classList.remove("open");$("#cartDrawer").setAttribute("aria-hidden","true");$("#cartButton").setAttribute("aria-expanded","false");document.body.classList.remove("lock")}
const deliveryFees={"George Town":150,"West Bay":250,"Red Bay":200,"Prospect":200,"Spotts":200,"Savannah":250,"Bodden Town":300,"East End":350,"North Side":400};
function deliveryEligible(i){const p=products.find(p=>p.id===i.id);return !!p?.delivery&&["Rough Terrain Cranes","Boom Trucks","Telehandlers"].includes(p.category)&&!["weekly","monthly"].includes(i.term)}
const hourlyBillingNote="*Additional hours worked outside of the 4 hour minimum will be billed at the current hourly rate*";
function hasHourlyEquipmentService(){return cart.some(i=>i.term==="hourly"&&["Rough Terrain Cranes","Boom Trucks","Telehandlers","Heavy Hauling"].includes(products.find(p=>p.id===i.id)?.category))}
function checkoutTermsText(){const terms=$(".contract").innerText;return hasHourlyEquipmentService()?terms:terms.replace(hourlyBillingNote, "")}
function needsJobDetails(){return cart.some(i=>["Rough Terrain Cranes","Boom Trucks","Telehandlers"].includes(products.find(p=>p.id===i.id)?.category))}
function deliveryEstimate(){const area=$("#areaSelect").value,eligible=cart.some(deliveryEligible);if(!eligible)return 0;if(area in deliveryFees)return deliveryFees[area];return null}
