function renderCheckout(){["#hourlyCheckoutNote","#hourlyContractNote"].forEach(selector=>$(selector).hidden=!hasHourlyEquipmentService());const fields=$("#jobDetailsFields");fields.hidden=!needsJobDetails();fields.disabled=!needsJobDetails();$("#checkoutItems").innerHTML=cart.map(i=>{const p=products.find(x=>x.id===i.id);return `<div class="checkout-item ${p.operatorService?"operator-line":""} ${p.quoteOnly?"quote-line":""}"><div><b>${lineName(i,p)}</b><strong>${lineTotal(i,p)}</strong></div><small>${lineRate(i,p)}${p.category==="Tools"?" · Pickup only":""}</small></div>`}).join("");const quotePending=hasQuoteItems();$("#checkoutSubtotal").textContent=money(equipmentSubtotal())+(quotePending?" + quote":"");const d=deliveryEstimate(),discount=rewardDiscount(),operatorTotal=operatorSubtotal();$("#checkoutOperatorRow").hidden=!operatorTotal;$("#checkoutOperatorSubtotal").textContent=money(operatorTotal);$("#checkoutRewardRow").hidden=!discount;$("#checkoutRewardLabel").textContent=discount?`${rewardsAccount.tier} rewards (${discount}%)`:"Rewards discount";$("#checkoutRewardDiscount").textContent=`−${money(rewardSavings())}`;$("#checkoutRewardNote").textContent=quotePending?"Manual-price items are excluded from this estimate and will be confirmed with availability.":discount?`${rewardsAccount.tier} discount is applied to equipment. Operator service is shown separately. Final availability and total are still confirmed manually.`:"Final availability and total are confirmed manually before fulfillment.";$("#checkoutDelivery").textContent=d===null?"To be confirmed":d===0?"No delivery fee":money(d);$("#checkoutTotal").textContent=money(discountedSubtotal()+(d||0))+((d===null||quotePending)?"+":"")}
function formRequest(){const f=new FormData($("#checkoutForm")),d=deliveryEstimate(),discount=rewardDiscount(),operatorTotal=operatorSubtotal(),quotePending=hasQuoteItems(),lines=["CAYMAN CRANE COMPANY — BOOKING REQUEST","",`Customer: ${f.get("customer_name")}`,`Company: ${f.get("company")||"—"}`,`Email: ${f.get("email")}`,`Phone: ${f.get("phone")}`,...(needsJobDetails()?[`Requested start: ${f.get("start_date")} at ${f.get("start_time")}`,`Area: ${f.get("area")}`,`Site address: ${f.get("site_address")}`]:[]),...(cart.some(i=>products.find(p=>p.id===i.id)?.category==="Tools")?["Tool rentals: Pickup only"]:[]),"",...(needsJobDetails()?[`Job details: ${f.get("job_details")}`,""]:[]),"BOOKING ITEMS:",...cart.map(i=>{const p=products.find(x=>x.id===i.id);return p.quoteOnly?`• ${lineName(i,p)} — quantity ${i.qty} — RATE TO BE CONFIRMED`:`• ${lineName(i,p)} — ${termLabels[i.term]} at ${money(p.rates[i.term])} × ${i.qty} — ${money(lineAmount(i))}`}),"",`Priced equipment estimate: ${money(equipmentSubtotal())}`,...(quotePending?["Manual-price items: To be confirmed"]:[]),...(operatorTotal?[`Operator service: ${money(operatorTotal)}`]:[]),...(discount?[`Approved ${rewardsAccount.tier} rewards discount (${discount}%): −${money(rewardSavings())}`]:[]),`Estimated delivery: ${d===null?"To be confirmed":d===0?"No fee":money(d)}`,`Estimated total: ${money(discountedSubtotal()+(d||0))}${d===null||quotePending?" plus items to be confirmed":""}`,...(hasHourlyEquipmentService()?[hourlyBillingNote]:[]),`Payment preference: ${f.get("payment_timing")==="deposit"?"Online booking deposit":"Pay after availability confirmation"}`,"",`Agreement accepted and signed by: ${f.get("signature")}`,`Customer initials: ${f.get("initials")}`,`Submitted: ${new Date().toLocaleString()}`,"","This request is pending manual acceptance by Cayman Crane Company."];return lines.join("\n")}
