// Native dialog provides keyboard focus containment and Escape-to-close.
const imageViewer = document.querySelector('#imageViewer');
let imageViewerTrigger = null;
document.addEventListener('click', event => {
  const trigger = event.target.closest('.image-enlarge');
  if (!trigger) return;
  const source = trigger.querySelector('img');
  if (!source) return;
  imageViewerTrigger = trigger;
  document.querySelector('#enlargedImage').src = source.currentSrc || source.src;
  document.querySelector('#enlargedImage').alt = source.alt;
  document.querySelector('#imageViewerTitle').textContent = source.alt;
  imageViewer.showModal();
});
document.querySelector('#closeImageViewer').onclick = () => imageViewer.close();
imageViewer.addEventListener('click', event => { if (event.target === imageViewer) imageViewer.close(); });
imageViewer.addEventListener('close', () => { if (imageViewerTrigger?.isConnected) imageViewerTrigger.focus(); });
